def reference(inputs):
    from decimal import Decimal
    vals = {}
    for k, v in inputs.items():
        n = number(v)
        if n is None:
            raise ValueError('unreadable')
        vals[k] = n
    years = cost = life = salv = None
    for k, n in vals.items():
        kl = k.lower()
        if 'elapsed' in kl:
            years = n
        elif 'original cost' in kl:
            cost = n
        elif 'useful life' in kl:
            life = n
        elif 'salvage' in kl:
            salv = n
    if years is None or cost is None or life is None or salv is None:
        raise ValueError('missing')
    if life <= 0 or years < 0:
        raise ValueError('bad')
    n = int(round(years))
    cost = Decimal(repr(cost))
    salv = Decimal(repr(salv))
    rate = Decimal(2) / Decimal(repr(life))
    bv = cost
    for _ in range(n):
        dep = bv * rate
        room = bv - salv
        if dep > room:
            dep = room
        bv = bv - dep
    return {'book value after the elapsed years in dollars': float(bv)}

