def reference(inputs):
    from decimal import Decimal, ROUND_HALF_UP
    keys = list(inputs.keys())
    def find(sub):
        for k in keys:
            if sub in k:
                return inputs[k]
        raise ValueError('missing')
    P = number(find('principal'))
    rate = number(find('interest rate'))
    freq = find('frequency').lower()
    term_text = find('term')
    tn = number(term_text)
    if P is None or rate is None or tn is None:
        raise ValueError('bad')
    fmap = [('semimonth', 24), ('bimonth', 6), ('biweek', 26), ('semiannual', 2), ('semi-annual', 2), ('twice', 2), ('monthly', 12), ('quarter', 4), ('annual', 1), ('yearly', 1), ('weekly', 52), ('daily', 365)]
    ppy = None
    for name, v in fmap:
        if name in freq:
            ppy = v
            break
    if ppy is None:
        raise ValueError('freq')
    t = term_text.lower()
    if 'month' in t:
        years = Decimal(repr(float(tn))) / Decimal(12)
    else:
        years = Decimal(repr(float(tn)))
    nd = years * ppy
    n = int(nd.to_integral_value(ROUND_HALF_UP))
    if abs(nd - n) > Decimal('0.000001') or n <= 0:
        raise ValueError('n')
    Pd = Decimal(repr(float(P)))
    r = Decimal(repr(float(rate))) / Decimal(100) / Decimal(ppy)
    if r == 0:
        pay = Pd / n
    else:
        g = (1 + r) ** n
        pay = Pd * r * g / (g - 1)
    cent = Decimal('0.01')
    pr = pay.quantize(cent, rounding=ROUND_HALF_UP)
    ti = (pr * n - Pd).quantize(cent, rounding=ROUND_HALF_UP)
    return {'monthly payment in dollars': pr, 'total interest in dollars': ti}
